-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Datenschutz > Personenbezogene Daten
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen personenbezogene Daten in einem IT-Betrieb gemäß DSGVO geschützt werden?', 2, '[{"text": "Ja", "correct": true, "because": "DSGVO verlangt Schutz personenbezogener Daten"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können personenbezogene Daten wie E-Mail-Adressen von Fachinformatikern ohne Einwilligung verarbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "DSGVO erfordert Einwilligung oder Rechtsgrundlage"}, {"text": "Ja", "correct": false, "because": "Verarbeitung ohne Einwilligung verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Name eines Mitarbeiters in einem IT-Betrieb ein personenbezogenes Datum?', 2, '[{"text": "Ja", "correct": true, "because": "Namen sind gemäß DSGVO personenbezogen"}, {"text": "Nein", "correct": false, "because": "Identifizierbare Daten sind geschützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen personenbezogene Daten in einem IT-Betrieb verschlüsselt gespeichert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Verschlüsselung ist eine empfohlene Sicherheitsmaßnahme nach DSGVO"}, {"text": "Nein", "correct": false, "because": "Technische Maßnahmen sind Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb personenbezogene Daten ohne Zweckbindung verarbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "DSGVO verlangt Zweckbindung"}, {"text": "Ja", "correct": false, "because": "Verarbeitung ohne Zweck verboten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt den Umgang mit personenbezogenen Daten in einem IT-Betrieb?', 2, '[{"text": "Datenschutz-Grundverordnung (DSGVO)", "correct": true, "because": "DSGVO ist die EU-weite Grundlage"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Beispiel für personenbezogene Daten in einem IT-Betrieb?', 3, '[{"text": "E-Mail-Adresse eines Mitarbeiters", "correct": true, "because": "Identifiziert eine Person"}, {"text": "Betriebssystemversion", "correct": false, "because": "Keine personenbezogene Information"}, {"text": "Serverstandort", "correct": false, "because": "Keine persönliche Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt personenbezogene Daten in einem IT-Betrieb?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Technische Maßnahme gemäß DSGVO"}, {"text": "Öffentliche Speicherung", "correct": false, "because": "Verstößt gegen DSGVO"}, {"text": "Keine Sicherung", "correct": false, "because": "Erhöht Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für den Schutz personenbezogener Daten in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Verantwortliche (z. B. Geschäftsführer)", "correct": true, "because": "DSGVO Art. 4 definiert Verantwortlichen"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht deren Pflicht"}, {"text": "Die Kunden", "correct": false, "because": "Kunden sind Betroffene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht einem IT-Betrieb bei Verstoß gegen den Schutz personenbezogener Daten?', 3, '[{"text": "Hohe Geldstrafen", "correct": true, "because": "DSGVO sieht Bußgelder bis 20 Mio. Euro vor"}, {"text": "Geringere Produktivität", "correct": false, "because": "Keine direkte Folge"}, {"text": "Weniger Kunden", "correct": false, "because": "Indirekte Folge"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Daten gelten als personenbezogen in einem IT-Betrieb?', 4, '[{"text": "Name eines Mitarbeiters", "correct": true, "because": "Identifiziert eine Person"}, {"text": "IP-Adresse eines Geräts", "correct": true, "because": "Kann einer Person zugeordnet werden"}, {"text": "Firmenlogo", "correct": false, "because": "Keine personenbezogene Information"}, {"text": "Telefonnummer eines Kunden", "correct": true, "because": "Personenbezogen gemäß DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen personenbezogene Daten in einem IT-Betrieb?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Erhöht Datensicherheit"}, {"text": "Zugangskontrollen", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verstößt gegen DSGVO"}, {"text": "Regelmäßige Backups", "correct": true, "because": "Schützt vor Datenverlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt die DSGVO an die Verarbeitung personenbezogener Daten in einem IT-Betrieb?', 4, '[{"text": "Rechtsgrundlage oder Einwilligung", "correct": true, "because": "Art. 6 DSGVO fordert Grundlage"}, {"text": "Zweckbindung", "correct": true, "because": "Daten nur für festgelegte Zwecke"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Speicherbegrenzung vorgeschrieben"}, {"text": "Datensparsamkeit", "correct": true, "because": "Nur notwendige Daten erheben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch unsachgemäßen Umgang mit personenbezogenen Daten in einem IT-Betrieb?', 3, '[{"text": "Bußgelder", "correct": true, "because": "DSGVO sanktioniert Verstöße"}, {"text": "Datenlecks", "correct": true, "because": "Unsicherheit führt zu Verlust"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein Risiko"}, {"text": "Imageschaden", "correct": true, "because": "Vertrauensverlust möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet den Umgang mit personenbezogenen Daten in einem IT-Betrieb von anderen Branchen?', 3, '[{"text": "Hohe Datenmenge durch IT-Systeme", "correct": true, "because": "IT verarbeitet oft viele Daten"}, {"text": "Technische Schutzmaßnahmen erforderlich", "correct": true, "because": "IT-spezifische Risiken"}, {"text": "Weniger Datenschutzvorschriften", "correct": false, "because": "DSGVO gilt überall"}, {"text": "Spezifische IT-Risiken wie Hacking", "correct": true, "because": "Cyberangriffe betreffen IT stärker"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Personenbezogene Daten müssen gemäß DSGVO geschützt werden. b) Eine E-Mail-Adresse ist kein personenbezogenes Datum.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO erfordert eine Rechtsgrundlage für die Verarbeitung personenbezogener Daten. b) Personenbezogene Daten dürfen ohne Zweckbindung verarbeitet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rechtsgrundlage ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt personenbezogene Daten in einem IT-Betrieb. b) Ein IT-Betrieb kann Verstöße gegen die DSGVO mit hohen Bußgeldern sanktionieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, b) ist falsch (Behörden sanktionieren)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Personenbezogene Daten umfassen Namen und Telefonnummern. b) Der Arbeitgeber ist für den Schutz dieser Daten verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Datenarten und Verantwortung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Datenleck kann einen Imageschaden für einen IT-Betrieb verursachen. b) Personenbezogene Daten dürfen ohne Sicherheitsmaßnahmen gespeichert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Imageschaden ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

